def transform(grid):
    h, w = len(grid), len(grid[0])
    # Uniform divider rows and columns partition the grid into panels.
    row_div = [i for i, row in enumerate(grid) if len(set(row)) == 1]
    col_div = [j for j in range(w) if len({grid[i][j] for i in range(h)}) == 1]
    def sections(size, divs):
        out=[]; start=0
        for x in divs:
            if x > start: out.append((start, x))
            start=x+1
        if start < size: out.append((start, size))
        return out
    rs, cs = sections(h, row_div), sections(w, col_div)
    # Use the panel with the most non-background marks as the source pattern.
    from collections import Counter
    vals = [grid[y][x] for y in range(h) if y not in row_div for x in range(w) if x not in col_div]
    background = Counter(vals).most_common(1)[0][0]
    candidates=[]
    for ri,(a,b) in enumerate(rs):
        for ci,(c,d) in enumerate(cs):
            panel=[row[c:d] for row in grid[a:b]]
            score=sum(v != background for row in panel for v in row)
            candidates.append((score, panel))
    pattern=max(candidates, key=lambda item:item[0])[1]
    out=[row[:] for row in grid]
    for a,b in rs:
        for c,d in cs:
            for y in range(a,b):
                for x in range(c,d):
                    out[y][x] = pattern[(y-a) % len(pattern)][(x-c) % len(pattern[0])]
    for y in row_div: out[y]=grid[y][:]
    for x in col_div:
        for y in range(h): out[y][x]=grid[y][x]
    return out
